package com.orderflow.notification.outbox;import com.orderflow.notification.config.OutboxProperties;import io.micrometer.core.instrument.*;import java.nio.charset.StandardCharsets;import java.util.UUID;import java.util.concurrent.TimeUnit;import org.apache.kafka.clients.producer.ProducerRecord;import org.apache.kafka.common.header.internals.RecordHeader;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;@Component public class OutboxPublisher{private final OutboxStore s;private final KafkaTemplate<String,String>k;private final OutboxProperties p;private final String owner=UUID.randomUUID().toString();public OutboxPublisher(OutboxStore s,KafkaTemplate<String,String>k,OutboxProperties p,MeterRegistry m){this.s=s;this.k=k;this.p=p;Gauge.builder("orderflow_outbox_backlog",s,OutboxStore::backlog).tag("service","notification-service").register(m);Gauge.builder("orderflow_outbox_failed",s,OutboxStore::failedCount).tag("service","notification-service").register(m);}@Scheduled(fixedDelayString="${app.outbox.poll-delay:500ms}",initialDelayString="${app.outbox.poll-delay:500ms}")public void publishDue(){s.claim(owner).forEach(this::send);}private void send(OutboxMessage m){var r=new ProducerRecord<String,String>(m.topic(),m.messageKey(),m.payload());r.headers().add(new RecordHeader("eventType",m.eventType().getBytes(StandardCharsets.UTF_8)));r.headers().add(new RecordHeader("eventVersion",Integer.toString(m.eventVersion()).getBytes(StandardCharsets.UTF_8)));try{k.send(r).get(p.sendTimeout().toMillis(),TimeUnit.MILLISECONDS);s.published(m.id(),owner);}catch(Exception e){s.failed(m,owner,e.getClass().getSimpleName());}}}
